au_companies = self.env.companies.filtered(lambda c: c.country_id.code == "AU") proportions = self.env["l10n_au.super.account"]._read_group( [("account_active", "=", True)], ["employee_id"], having=[("proportion:sum", "!=", 1)], ) invalid_employees = self.env['hr.employee'].browse([employee.id for employee, in proportions])
